/* BOARD//LAB 3.0 PCB Design Studio — offline graphical PCB training editor.
   Training data only; export requires KiCad ERC/DRC, supplier footprint and manufacturing validation. */
(()=>{
'use strict';
const K=window.BoardPCB;if(!K)return;
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const noHTML=s=>String(s||'').replace(/[\x00-\x1f<>]/g,'').slice(0,140);
const uid=(key)=>key+Math.random().toString(36).slice(2,8)+Date.now().toString(36);
const fmt=(n,d=2)=>Number(n||0).toFixed(d);
const storeKey='boardlab.pcb.project.v3', progressKey='boardlab.pcb.lessons.v3';
const parseSaved=()=>{try{return K.validateImport(JSON.parse(localStorage.getItem(storeKey)))}catch{return K.getTemplate('led')}};
let board=parseSaved(),tool='select',view='layout',armed=null,selected=null,route=null,schConnect=false,schFirst=null,visible={top:true,bottom:true,rats:true,iso:false},undo=[],redo=[],drag=null,active=false,lessonIndex=0;
let completed=[];try{completed=JSON.parse(localStorage.getItem(progressKey)||'[]');if(!Array.isArray(completed))completed=[]}catch{}
const snap=v=>{let g=Number($('pcbGrid').value)||.5;return K.round(Math.round(v/g)*g,3)};
const src=()=>JSON.parse(JSON.stringify(board));
function notice(message,error=false){let t=$('toast');if(!t)return;t.textContent=message;t.classList.remove('hidden');t.classList.toggle('error',error);clearTimeout(notice.timer);notice.timer=setTimeout(()=>t.classList.add('hidden'),3100)}
function saveLocal(){try{localStorage.setItem(storeKey,JSON.stringify(board))}catch{}}
function commit(fn){const before=JSON.stringify(board);try{fn()}catch(e){notice(e.message,true);return}if(JSON.stringify(board)!==before){undo.push(before);if(undo.length>80)undo.shift();redo=[];board.rev=(board.rev||1)+1;saveLocal();render()}}
function undoEdit(){if(!undo.length)return notice('No earlier PCB revision.');redo.push(JSON.stringify(board));board=JSON.parse(undo.pop());route=null;selected=null;saveLocal();render()}
function redoEdit(){if(!redo.length)return notice('No redo step.');undo.push(JSON.stringify(board));board=JSON.parse(redo.pop());route=null;selected=null;saveLocal();render()}
function setTool(next){tool=next;armed=null;route=null;document.querySelectorAll('[data-pcb-tool]').forEach(b=>b.classList.toggle('active',b.dataset.pcbTool===next));renderPalette();renderBoard();$('pcbRouteStatus').textContent=({select:'SELECT / DRAG PARTS',route:'SELECT FIRST NET PAD',via:'VIA · CHOOSE NET',delete:'DELETE COPPER OR PART'})[next]}
function setView(next){view=next;document.querySelectorAll('[data-pcb-view]').forEach(b=>b.classList.toggle('active',b.dataset.pcbView===next));['layout','schematic','stackup','learning','release'].forEach(k=>{$(k==='stackup'?'pcbStackPane':'pcb'+k[0].toUpperCase()+k.slice(1)+'Pane').classList.toggle('hidden',k!==next)});render()}
function show(){if(active)return;active=true;const w=document.querySelector('.workspace');w.classList.add('hidden');$('pcbStudio').classList.remove('hidden');document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab==='pcb'));render();window.scrollTo({top:0,behavior:'instant'})}
function hide(){if(!active)return;active=false;document.querySelector('.workspace').classList.remove('hidden');$('pcbStudio').classList.add('hidden')}
function loadTemplate(which){const next=which==='routed'?K.routedExample():K.getTemplate(which);commit(()=>{board=next;selected=null;route=null});setTool('select');setView('layout');notice(`Loaded ${next.title}`)}
function downloadFile(name,data,type='text/plain;charset=utf-8'){let b=new Blob([data],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1500)}
function newNetFromPad(p){return p.net||($('pcbActiveNet').value||'')}
function populateNets(){const previous=$('pcbActiveNet').value;let names=K.nets(board);let current=(route?.net)||previous;const html=names.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');$('pcbActiveNet').innerHTML=html||'<option value="">(assign net first)</option>';$('pcbActiveNet').value=names.includes(current)?current:(names[0]||'')}
function renderPalette(){const query=String($('pcbSearchPart').value||'').toLowerCase();$('pcbPalette').innerHTML=Object.entries(K.COMPONENTS).filter(([k,d])=>(k+' '+d.title).toLowerCase().includes(query)).map(([key,def])=>`<button data-pcb-place="${esc(key)}" class="${armed===key?'armed':''}"><span>${esc(key)}</span>${esc(def.title)}</button>`).join('')||'<div class="pcb-quiet">No matching footprints.</div>';
$('pcbPalette').querySelectorAll('button').forEach(b=>b.onclick=()=>{armed=b.dataset.pcbPlace;tool='select';route=null;document.querySelectorAll('[data-pcb-tool]').forEach(x=>x.classList.toggle('active',x.dataset.pcbTool===tool));renderPalette();$('pcbRouteStatus').textContent='PLACE '+armed+' ON BOARD';notice('Click an empty board location to place '+armed)})}
const padColor=n=>n==='GND'?'#8beed7':n?.includes('5V')||n?.includes('VIN')?'#f7c57d':n?.includes('3V')?'#bdeaf8':'#eddfb5';
const netColor=n=>{let i=0;for(let c of n)i=((i<<5)-i+c.charCodeAt(0))|0;return ['#58e6d0','#f6ce73','#85bffa','#b2d482','#eea5b3','#d2adf2','#7ed8e4'][Math.abs(i)%7]};
function svgPoint(e){const svg=$('pcbBoardSvg'),pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const ctm=svg.getScreenCTM();if(!ctm)return{x:0,y:0};const out=pt.matrixTransform(ctm.inverse());return{x:K.round(out.x,3),y:K.round(out.y,3)}}
function nearestPad(p,net,range=1.3){let found=null,min=range;K.allPads(board).forEach(q=>{let d=K.dist(p,q);if((!net||q.net===net)&&d<min){min=d;found=q}});return found}
function routeClick(pos,pad){if(!route){const net=pad?.net||$('pcbActiveNet').value;if(!net)return notice('Assign a net to the pad first, or select an active net.',true);if(pad&&pad.net!==net)return notice('Pad net mismatch',true);route={net,layer:$('pcbActiveLayer').value,points:[pad?{x:pad.x,y:pad.y}:pos]};$('pcbRouteStatus').textContent='ROUTING '+net+' · CLICK TARGET PAD';renderBoard();return}
if(pad){if(pad.net!==route.net)return notice('Short-circuit prevented: this target belongs to '+(pad.net||'an unassigned net'),true);let p={x:pad.x,y:pad.y};if(K.dist(p,route.points[route.points.length-1])>.01)route.points.push(p);if(route.points.length>=2)finishRoute();else notice('Select a different pad to connect.');return}
if(K.dist(pos,route.points[route.points.length-1])>.01){route.points.push(pos);$('pcbRouteStatus').textContent='WAYPOINT ADDED · CLICK TARGET PAD / DOUBLE-CLICK TO FINISH';renderBoard()}}
function finishRoute(){if(!route||route.points.length<2)return;let entry={id:uid('t'),net:route.net,layer:route.layer,width:+$('pcbTraceWidth').value||.4,points:route.points};route=null;commit(()=>board.tracks.push(entry));notice('Copper trace added. Check DRC for clearance and connectivity.')}
function selectThing(kind,id){selected={kind,id};renderInspector();renderBoard()}
function screenSvg(e){const p=svgPoint(e);$('pcbCoord').textContent=`X: ${fmt(p.x)}  Y: ${fmt(p.y)} mm`;return{x:snap(p.x),y:snap(p.y)}}
function selectPad(pin){const p=K.allPads(board).find(q=>q.part===pin.part&&q.pin===pin.pin);if(!p)return;if(tool==='route'){routeClick({x:p.x,y:p.y},p);return}if(tool==='delete')return notice('Select whole component for deletion.');selected={kind:'part',id:p.part};$('pcbActiveNet').value=p.net||$('pcbActiveNet').value;renderInspector();renderBoard()}
function onBoardClick(e){if(visible.iso){notice('Switch to TOP view for accurate placement and routing.',true);return}if(drag?.moved){drag=null;return}let p=screenSvg(e);if(p.x<0||p.y<0||p.x>board.width||p.y>board.height)return;if(armed){let type=armed;commit(()=>board.parts.push(K.newPart(board,type,p.x,p.y)));armed=null;renderPalette();return}
if(tool==='route'){routeClick(p,nearestPad(p,route?.net||$('pcbActiveNet').value,0.9));return}
if(tool==='via'){const net=$('pcbActiveNet').value;if(!net)return notice('Choose or assign a net before placing a via.',true);commit(()=>board.vias.push({id:uid('v'),net,x:p.x,y:p.y,diameter:+board.rules.viaDiameter||.65,drill:+board.rules.viaDrill||.3}));notice('Via connects front and back copper for selected net.');return}
selected=null;renderInspector();renderBoard()}
function renderBoard(){const svg=$('pcbBoardSvg');if(!svg)return;
svg.setAttribute('viewBox',`${-5} ${-5} ${board.width+10} ${board.height+10}`);$('pcbBoardName').textContent=board.title;
const bg=`<defs><pattern id="pcb-dot" patternUnits="userSpaceOnUse" width="2" height="2"><circle cx=".4" cy=".4" r=".075" fill="#93cfbe" opacity=".23"/></pattern><linearGradient id="pcb-bg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#175e59"/><stop offset="1" stop-color="#083a38"/></linearGradient><filter id="pcb-glow"><feGaussianBlur stdDeviation=".22" result="g"/><feMerge><feMergeNode in="g"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>`;
let items=[bg,`<rect x="0" y="0" width="${board.width}" height="${board.height}" rx="1.3" fill="url(#pcb-bg)" stroke="#75c2a6" stroke-width=".55"/>`, `<rect x=".5" y=".5" width="${board.width-1}" height="${board.height-1}" rx="1" fill="url(#pcb-dot)" pointer-events="none"/>`];
// Copper artwork and routing are back-to-front, selected net is highlighted by trace overlay.
if(visible.bottom)board.tracks.filter(t=>t.layer==='B.Cu').forEach(t=>items.push(traceSVG(t)));
if(visible.top)board.tracks.filter(t=>t.layer==='F.Cu').forEach(t=>items.push(traceSVG(t)));
board.vias.forEach(v=>{const chosen=selected?.kind==='via'&&selected.id===v.id;items.push(`<g class="pcb-via" data-via="${esc(v.id)}"><circle cx="${v.x}" cy="${v.y}" r="${v.diameter/2}" fill="#dfb970" stroke="${chosen?'#fff':'#bad1aa'}" stroke-width=".11"/><circle cx="${v.x}" cy="${v.y}" r="${v.drill/2}" fill="#081d20"/></g>`)});
let pads=K.allPads(board);
if(visible.rats){const groups={};pads.forEach(p=>{if(p.net)(groups[p.net]??=[]).push(p)});for(const [net,pp] of Object.entries(groups)){for(let i=1;i<pp.length;i++)items.push(`<line x1="${pp[i-1].x}" y1="${pp[i-1].y}" x2="${pp[i].x}" y2="${pp[i].y}" stroke="${netColor(net)}" stroke-width=".12" stroke-dasharray=".7 .75" opacity=".48" pointer-events="none"/>`)}}
for(const part of board.parts){const d=K.COMPONENTS[part.type];if(!d)continue;const selectedPart=selected?.kind==='part'&&selected.id===part.id;let body=part.type==='HOLE_M3'?`<circle r="3.1" fill="#082e2c" stroke="#9ec9c9" stroke-width=".18"/><circle r="1.6" fill="#082024" stroke="#6c9f9f" stroke-width=".2"/>`:`<rect class="pcb-body" x="${-d.body[0]/2}" y="${-d.body[1]/2}" width="${d.body[0]}" height="${d.body[1]}" rx=".25" fill="#1b343c" stroke="${d.silk}" stroke-width=".16"/><path d="M${-d.body[0]/2+.18},${-d.body[1]/2+.22} h.45" stroke="#e6f8e0" stroke-width=".13"/>`;
items.push(`<g class="pcb-component ${selectedPart?'pcb-selected':''}" data-part="${esc(part.id)}" transform="translate(${part.x},${part.y}) rotate(${part.angle})">${body}<text class="pcb-silk-label" text-anchor="middle" x="0" y="${-d.body[1]/2-1.5}">${esc(part.ref)}</text></g>`)}
// Pads after packages so each is targetable.
pads.forEach(p=>{let activeNet=p.net&&p.net===$('pcbActiveNet').value;items.push(`<rect class="pcb-pad" data-pad-part="${esc(p.part)}" data-pad-pin="${esc(p.pin)}" x="${p.x-p.w/2}" y="${p.y-p.h/2}" width="${p.w}" height="${p.h}" rx=".13" fill="${padColor(p.net)}" stroke="${activeNet?'#fff8bd':'#7f746a'}" stroke-width="${activeNet?'.18':'.08'}"/>`)});
if(route){let p=route.points;items.push(`<polyline class="pcb-route-preview" points="${p.map(pt=>pt.x+','+pt.y).join(' ')}"/>`);for(const pt of p)items.push(`<circle cx="${pt.x}" cy="${pt.y}" r=".37" fill="#fcf5a0" pointer-events="none"/>`)}
items.push(`<text x="${board.width-1}" y="${board.height+3}" text-anchor="end" font-size="1.3" fill="#a5ced2">${esc(board.title)} · ${board.layers}L · ${esc(String(board.rev))}</text>`,`<path d="M0 ${board.height+2}H10m-10 -1v2m10 -2v2" stroke="#9ac5be" stroke-width=".18" fill="none"/><text x="5" y="${board.height+3.6}" font-size="1.1" fill="#a5ced2" text-anchor="middle">10 mm</text>`);
svg.innerHTML=items.join('');
svg.querySelectorAll('[data-part]').forEach(el=>{el.addEventListener('pointerdown',beginDrag);el.onclick=e=>{e.stopPropagation();if(drag?.moved){drag=null;return}if(tool==='delete'){const id=el.dataset.part;commit(()=>{board.parts=board.parts.filter(p=>p.id!==id)});selected=null;return}selectThing('part',el.dataset.part)}});
svg.querySelectorAll('[data-pad-part]').forEach(el=>el.onclick=e=>{e.stopPropagation();selectPad({part:el.dataset.padPart,pin:el.dataset.padPin})});
svg.querySelectorAll('[data-trace]').forEach(el=>el.onclick=e=>{e.stopPropagation();const id=el.dataset.trace;if(tool==='delete'){commit(()=>board.tracks=board.tracks.filter(t=>t.id!==id));selected=null;return}selectThing('trace',id)});
svg.querySelectorAll('[data-via]').forEach(el=>el.onclick=e=>{e.stopPropagation();const id=el.dataset.via;if(tool==='delete'){commit(()=>board.vias=board.vias.filter(v=>v.id!==id));selected=null;return}selectThing('via',id)});
$('pcbSelectedNetSummary').textContent='NET: '+($('pcbActiveNet').value||'—');$('pcbFooterMetrics').textContent=`${board.parts.length} parts · ${board.tracks.length} tracks · ${board.vias.length} vias · ${board.layers} layers`;
}
function traceSVG(t){return `<polyline class="pcb-trace ${selected?.kind==='trace'&&selected.id===t.id?'selected':''}" data-trace="${esc(t.id)}" points="${t.points.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="${t.layer==='B.Cu'?'#75afeb':'#e6b467'}" stroke-width="${t.width}" stroke-linecap="round" stroke-linejoin="round" opacity=".92"/>`}
function beginDrag(e){if(tool!=='select'||armed||visible.iso)return;const id=e.currentTarget.dataset.part,p=board.parts.find(p=>p.id===id);if(!p)return;drag={id,start:svgPoint(e),x:p.x,y:p.y,moved:false};e.currentTarget.setPointerCapture(e.pointerId)}
function dragMove(e){if(!drag)return;const p=svgPoint(e),target=board.parts.find(x=>x.id===drag.id);if(!target)return;const nx=K.clamp(snap(drag.x+p.x-drag.start.x),2,board.width-2),ny=K.clamp(snap(drag.y+p.y-drag.start.y),2,board.height-2);if(Math.abs(nx-target.x)+Math.abs(ny-target.y)>.01){if(!drag.moved){undo.push(JSON.stringify(board));if(undo.length>80)undo.shift();redo=[]}drag.moved=true;target.x=nx;target.y=ny;renderInspector();const group=$('pcbBoardSvg').querySelector(`[data-part="${CSS.escape(target.id)}"]`);if(group)group.setAttribute('transform',`translate(${nx},${ny}) rotate(${target.angle})`);}}
function dragFinish(){if(!drag)return;if(drag.moved){board.rev++;saveLocal();selected={kind:'part',id:drag.id};drag.moved=false;render()}drag=null}
function renderInspector(){const el=$('pcbPropertyPanel');if(!selected){el.innerHTML='<strong>Nothing selected</strong><p class="pcb-quiet">Click a footprint, copper trace, via or pad to inspect geometry and net assignment.</p>';return}
if(selected.kind==='part'){let p=board.parts.find(p=>p.id===selected.id);if(!p){selected=null;return renderInspector()}let d=K.COMPONENTS[p.type];el.innerHTML=`<strong>${esc(p.ref)} · ${esc(d.title)}</strong><p class="pcb-quiet">${esc(d.footprint)}</p><label>Reference<input id="pcbEditRef" value="${esc(p.ref)}" maxlength="20"></label><label>Part value / specification<input id="pcbEditValue" value="${esc(p.value)}" maxlength="140"></label><div class="pcb-mini-row"><label>X (mm)<input id="pcbEditX" type="number" value="${p.x}" step=".5"></label><label>Y (mm)<input id="pcbEditY" type="number" value="${p.y}" step=".5"></label></div><label>Rotation<select id="pcbEditAngle">${[0,90,180,270].map(a=>`<option value="${a}" ${a===(p.angle||0)?'selected':''}>${a}°</option>`).join('')}</select></label><div class="pcb-divider"></div><div class="section-label">PAD → ELECTRICAL NET</div>${K.padsFor(p).map(pd=>`<div class="pcb-pad-editor"><label>${esc(pd.ref)} / PIN ${esc(pd.pin)} <input data-padnet="${esc(pd.pin)}" value="${esc(pd.net)}" placeholder="e.g. GND"></label></div>`).join('')||'<p class="pcb-quiet">Non-plated mechanical mounting hole.</p>'}<button class="pcb-primary" id="pcbUpdatePart" style="width:100%;margin-top:12px">APPLY COMPONENT EDITS</button><button id="pcbDeletePart" style="width:100%;margin-top:6px">REMOVE FOOTPRINT</button>`;
$('pcbUpdatePart').onclick=()=>{const ref=noHTML($('pcbEditRef').value.trim()).replace(/\s/g,''),v=noHTML($('pcbEditValue').value),x=+$('pcbEditX').value,y=+$('pcbEditY').value,angle=+$('pcbEditAngle').value;if(!ref||ref.length>20||board.parts.some(a=>a.id!==p.id&&a.ref===ref))return notice('Reference must be unique and nonempty.',true);if(!Number.isFinite(x)||!Number.isFinite(y)||x<0||y<0||x>board.width||y>board.height)return notice('Component is outside the board.',true);const nets={};el.querySelectorAll('[data-padnet]').forEach(a=>nets[a.dataset.padnet]=a.value.trim().toUpperCase().replace(/[^A-Z0-9_+\-.]/g,'').slice(0,60));commit(()=>{p.ref=ref;p.value=v;p.x=x;p.y=y;p.angle=angle;p.nets=nets});};
$('pcbDeletePart').onclick=()=>{commit(()=>{board.parts=board.parts.filter(a=>a.id!==p.id)});selected=null;render()};return}
if(selected.kind==='trace'){let t=board.tracks.find(t=>t.id===selected.id);if(!t){selected=null;return renderInspector()}el.innerHTML=`<strong>${esc(t.id)} · ${esc(t.net)}</strong><p class="pcb-quiet">Copper path · ${esc(t.layer)} · ${K.pathLength(t).toFixed(2)} mm</p><label>Net<select id="pcbEditNet">${K.nets(board).map(n=>`<option value="${esc(n)}" ${n===t.net?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label>Width (mm)<input id="pcbEditWidth" type="number" min=".05" max="6" step=".05" value="${t.width}"></label><label>Layer<select id="pcbEditTrackLayer">${['F.Cu','B.Cu'].map(n=>`<option ${n===t.layer?'selected':''}>${n}</option>`).join('')}</select></label><button id="pcbApplyTrace" class="pcb-primary" style="width:100%;margin-top:12px">UPDATE COPPER</button><button id="pcbDeleteTrace" style="width:100%;margin-top:6px">REMOVE TRACE</button>`;
$('pcbApplyTrace').onclick=()=>{const w=+$('pcbEditWidth').value;if(!Number.isFinite(w)||w<.05||w>6)return notice('Valid width is 0.05–6 mm.',true);commit(()=>{t.width=w;t.net=$('pcbEditNet').value;t.layer=$('pcbEditTrackLayer').value})};$('pcbDeleteTrace').onclick=()=>{commit(()=>board.tracks=board.tracks.filter(a=>a.id!==t.id));selected=null;render()};return}
if(selected.kind==='via'){let v=board.vias.find(v=>v.id===selected.id);if(!v){selected=null;return renderInspector()}el.innerHTML=`<strong>${esc(v.id)} · Plated through via</strong><p class="pcb-quiet">Connects F.Cu and B.Cu. Drill/annular ring rules require fabrication validation.</p><label>Via net<select id="pcbEditViaNet">${K.nets(board).map(n=>`<option value="${esc(n)}" ${v.net===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label><div class="pcb-mini-row"><label>Drill (mm)<input id="pcbEditDrill" type="number" min=".2" step=".05" value="${v.drill}"></label><label>Copper dia. (mm)<input id="pcbEditVDiam" type="number" min=".4" step=".05" value="${v.diameter}"></label></div><button class="pcb-primary" id="pcbApplyVia" style="width:100%;margin-top:12px">UPDATE VIA</button><button id="pcbDeleteVia" style="width:100%;margin-top:6px">REMOVE VIA</button>`;$('pcbApplyVia').onclick=()=>{let d=+$('pcbEditDrill').value,r=+$('pcbEditVDiam').value;if(!Number.isFinite(d)||!Number.isFinite(r)||d<=0||r<=d)return notice('Via copper diameter must exceed drill diameter.',true);commit(()=>{v.net=$('pcbEditViaNet').value;v.drill=d;v.diameter=r})};$('pcbDeleteVia').onclick=()=>{commit(()=>board.vias=board.vias.filter(a=>a.id!==v.id));selected=null;render()};}
}
function renderDRC(){const result=K.check(board);$('pcbDrcSummary').innerHTML=`<div class="${result.errors?'pcb-bad':''}"><strong>${result.errors}</strong><small>ERRORS</small></div><div class="${result.warnings?'pcb-warn':''}"><strong>${result.warnings}</strong><small>WARNINGS</small></div><div><strong>${result.percent}%</strong><small>CONNECTED</small></div>`;$('pcbDrcSmall').textContent=`${result.errors} ERRORS · ${result.warnings} WARNINGS · ${result.percent}% COPPER CONNECTED`;
$('pcbIssues').innerHTML=result.issues.slice(0,90).map(i=>`<button class="pcb-issue ${i.level}" data-issue-id="${esc(i.id||'')}"><span>${esc(i.level.toUpperCase())} · ${esc(i.code)}</span>${esc(i.message)}</button>`).join('')||'<p class="pcb-quiet">Training DRC found no problems. This is not a manufacturing clearance.</p>';
$('pcbIssues').querySelectorAll('[data-issue-id]').forEach(b=>b.onclick=()=>{let id=b.dataset.issueId;if(board.parts.some(p=>p.id===id))selectThing('part',id);else if(board.tracks.some(t=>t.id===id))selectThing('trace',id);else if(board.vias.some(v=>v.id===id))selectThing('via',id);setView('layout')});
return result}
function renderSchematic(){let svg=$('pcbSchematicSvg'),netNames=K.nets(board),ps=board.parts;let rowHeight=68,cols=3,rows=Math.max(1,Math.ceil(ps.length/cols)),height=Math.max(470,80+rows*rowHeight);svg.setAttribute('viewBox',`0 0 1080 ${height}`);
let html=[`<rect width="1080" height="${height}" fill="#0a2331"/>`,`<text x="24" y="28" font-size="15" fill="#a5e7d6" font-family="sans-serif" font-weight="bold">COMPONENT-TO-NET CONNECTIVITY  ·  CLICK A PART TO CROSS-PROBE LAYOUT</text>`];
const schNets={};ps.forEach((part,i)=>{const col=i%cols,row=Math.floor(i/cols),x=30+col*353,y=55+row*rowHeight;K.padsFor(part).slice(0,5).forEach((pin,j)=>{if(pin.net)(schNets[pin.net]??=[]).push({x:x+13+j*62+28,y:y+43})})});let connections=[];for(const [net,points] of Object.entries(schNets))for(let i=1;i<points.length;i++)connections.push(`<path d="M${points[i-1].x} ${points[i-1].y} L${points[i].x} ${points[i].y}" stroke="${netColor(net)}" stroke-width="2" opacity=".48" fill="none" stroke-dasharray="4 3"/>`);html.splice(2,0,...connections);
for(let i=0;i<ps.length;i++){let p=ps[i],col=i%cols,row=Math.floor(i/cols),x=30+col*353,y=55+row*rowHeight,def=K.COMPONENTS[p.type],pins=K.padsFor(p);html.push(`<g data-sch-part="${esc(p.id)}" style="cursor:pointer"><rect x="${x}" y="${y}" width="323" height="57" rx="5" fill="${selected?.id===p.id?'#2b645c':'#143745'}" stroke="#5a8b8d"/><text x="${x+11}" y="${y+18}" font-size="14" fill="#ecf9ef" font-family="sans-serif" font-weight="bold">${esc(p.ref)} · ${esc(def.label)}</text><text x="${x+11}" y="${y+31}" font-size="10" fill="#9fbbc3">${esc(p.value).slice(0,43)}</text>`);pins.slice(0,5).forEach((pin,j)=>{let xx=x+13+j*62;html.push(`<g class="pcb-sch-pin" data-sch-part="${esc(p.id)}" data-sch-pin="${esc(pin.pin)}"><rect x="${xx}" y="${y+36}" rx="2" width="57" height="15" fill="${netColor(pin.net||'?')}" opacity=".78"/><text x="${xx+2}" y="${y+46.5}" fill="#062332" font-size="9" font-weight="bold">${esc(pin.pin)}:${esc(pin.net||'NC').slice(0,9)}</text></g>`)});html.push('</g>')}
html.push(`<text x="35" y="${height-14}" fill="#8db1c0" font-size="11">${netNames.length} electrical nets · SVG visualization is a net map, not a symbol-accurate schematic · run KiCad ERC before manufacture</text>`);
svg.innerHTML=html.join('');
let toolbar=$('pcbSchematicPane').querySelector('.pcb-schematic-actions');if(!toolbar){toolbar=document.createElement('div');toolbar.className='pcb-schematic-actions';$('pcbSchematicPane').insertBefore(toolbar,$('pcbSchematicPane').querySelector('.pcb-schematic-scroll'))}
toolbar.innerHTML=`<button id="pcbSchConnect" class="${schConnect?'active':''}">⌁ CONNECT PINS</button><button id="pcbSchCancel">CANCEL</button><span>${schFirst?'SELECT SECOND PIN':schConnect?'CLICK FIRST PIN TO CONNECT': 'INSPECT MODE · CLICK COMPONENT OR PIN'}</span>`;
$('pcbSchConnect').onclick=()=>{schConnect=true;schFirst=null;renderSchematic()};$('pcbSchCancel').onclick=()=>{schConnect=false;schFirst=null;renderSchematic()};
svg.querySelectorAll('[data-sch-pin]').forEach(n=>n.addEventListener('click',e=>{e.stopPropagation();let id=n.dataset.schPart,pin=n.dataset.schPin,p=board.parts.find(x=>x.id===id);if(!p)return;selected={kind:'part',id};if(!schConnect){renderInspector();renderBoard();renderSchematic();return}if(!schFirst){schFirst={id,pin};notice('Choose a second pin to connect electrically.');renderSchematic();return}let a=board.parts.find(x=>x.id===schFirst.id),n1=a?.nets?.[schFirst.pin]||'',n2=p.nets?.[pin]||'';if(schFirst.id===id&&schFirst.pin===pin){schFirst=null;renderSchematic();return}if(n1&&n2&&n1!==n2){schFirst=null;notice('Connection blocked: distinct named nets. Reassign one pad explicitly in the inspector if this is intentional.',true);renderSchematic();return}let net=n1||n2||('NET_'+String(K.nets(board).length+1).padStart(2,'0'));commit(()=>{a.nets[schFirst.pin]=net;p.nets[pin]=net});schFirst=null;notice('Pins assigned to net '+net);renderSchematic()}));
svg.querySelectorAll('g[data-sch-part]').forEach(n=>n.addEventListener('click',e=>{e.stopPropagation();selected={kind:'part',id:n.dataset.schPart};renderInspector();renderBoard();renderSchematic()}));
let pane=$('pcbSchematicPane'),list=pane.querySelector('.pcb-net-table');if(!list){list=document.createElement('div');list.className='pcb-net-table';pane.insertBefore(list,pane.querySelector('.pcb-note'))}
list.innerHTML=`<div class="pcb-panel" style="margin:12px 15px"><h3>Electrical nets · ${netNames.length} assigned</h3><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:8px">${netNames.map(n=>`<button class="pcb-issue" data-select-net="${esc(n)}"><strong style="color:${netColor(n)}">${esc(n)}</strong> · ${K.allPads(board).filter(p=>p.net===n).map(p=>p.ref+'.'+p.pin).join(' · ')}</button>`).join('')||'No nets assigned. Add components and assign their pad nets in the inspector.'}</div></div>`;list.querySelectorAll('[data-select-net]').forEach(b=>b.onclick=()=>{$('pcbActiveNet').value=b.dataset.selectNet;setView('layout')})
}
function renderStackup(){const s=board.stackup,template=`<div class="pcb-panel"><h3>Layer stackup engineering</h3><p>Choose two or four physical copper layers. The graphical editor routes on F.Cu and B.Cu; inner copper planes are shown conceptually only. A real manufacturer must provide dielectric thicknesses, dielectric constant versus frequency, copper weights, impedance coupons and via capabilities.</p><div class="pcb-stack-controls"><label>Physical layers<select id="pcbStackLayers"><option value="2" ${board.layers===2?'selected':''}>2 · top / bottom</option><option value="4" ${board.layers===4?'selected':''}>4 · top / GND / PWR / bottom</option></select></label><label>Nominal total thickness (mm)<input id="pcbStackThickness" type="number" min=".4" max="3.2" step=".1" value="${s.thickness}"></label><label>Relative dielectric permittivity εr<input id="pcbStackEr" type="number" min="2" max="12" step=".1" value="${s.er}"></label><label>Copper thickness (mm)<input id="pcbStackCopper" type="number" min=".01" max=".14" step=".005" value="${s.copper}"></label><label>Signal-to-reference dielectric (mm)<input id="pcbStackH" type="number" min=".05" max="1.7" step=".01" value="${s.signalHeight}"></label><label>Signal trace width (mm)<input id="pcbCalcWidth" type="number" min=".05" max="5" step=".05" value="0.35"></label><label>Trace length (mm)<input id="pcbCalcLength" type="number" min="1" max="5000" step="1" value="65"></label><label>DC current (A)<input id="pcbCalcCurrent" type="number" min="0" max="20" step=".1" value="0.3"></label><label>Target impedance (Ω)<input id="pcbCalcTarget" type="number" min="30" max="150" step="1" value="50"></label></div><button class="pcb-primary" id="pcbApplyStack" style="margin-top:13px">APPLY STACKUP ASSUMPTIONS</button><div class="pcb-layer-figure" id="pcbLayerDiagram"></div><div class="pcb-calc-result" id="pcbEngineeringResult"></div><div class="pcb-warning" style="margin-top:14px">These are first-order educational approximations: this resistance result ignores temperature rise and plating variation; the microstrip closed-form estimate does not validate differential impedance, dispersion, copper roughness, solder mask, reference-plane integrity or RF performance. IPC-2152 current capacity and a fabricator-approved impedance solver are required for real designs.</div></div><div class="pcb-panel"><h3>Return paths and power integrity</h3><p><strong style="color:#a7edda">Signal return:</strong> keep a continuous nearby reference plane and avoid crossing plane splits. <strong style="color:#a7edda">Decoupling:</strong> reduce loop inductance by placing the capacitor close to the IC supply and return pins. <strong style="color:#a7edda">Switching power:</strong> minimize high-di/dt hot-loop area, keep the switch node compact, respect controller layout guidelines, and separate sensitive feedback.</p><p><strong>Modern boards:</strong> use controlled stackups for USB, PCIe, DDR and high-speed interfaces; budget connectors, insertion loss, skew, crosstalk, via transitions and manufacturing variation. This training editor does not route coupled differential pairs or length-match buses.</p></div>`;
$('pcbStackPane').innerHTML=template;
const getNum=(id,lo,hi)=>K.clamp(+$(`${id}`).value||lo,lo,hi);
function compute(){let layers=+$('pcbStackLayers').value,spec={thickness:getNum('pcbStackThickness',.4,3.2),er:getNum('pcbStackEr',2,12),copper:getNum('pcbStackCopper',.01,.14),signalHeight:getNum('pcbStackH',.05,1.7)};let w=getNum('pcbCalcWidth',.05,5),L=getNum('pcbCalcLength',1,5000),I=getNum('pcbCalcCurrent',0,20),zTarget=getNum('pcbCalcTarget',30,150),loss=K.copperLoss(L,w,spec.copper,I),z=K.microstrip(w,spec.signalHeight,spec.er,spec.copper),tw=K.widthForZ(zTarget,spec.signalHeight,spec.er,spec.copper);
$('pcbEngineeringResult').innerHTML=`<div><strong>${fmt(z,1)} Ω</strong><small>outer microstrip (rough)</small></div><div><strong>${fmt(tw,3)} mm</strong><small>width estimate for ${zTarget} Ω</small></div><div><strong>${fmt(loss.resistance,4)} Ω</strong><small>DC resistance · ${L} mm</small></div><div><strong>${fmt(loss.drop*1000,2)} mV</strong><small>ohmic voltage drop @ ${I} A</small></div>`;
let names=layers===4?[['Top copper / signal','#e7b673'],['Prepreg / controlled dielectric','#234858'],['Inner 1 / GND reference','#74e2b0'],['Core dielectric','#28525f'],['Inner 2 / PWR or signal','#a0c7ff'],['Prepreg / controlled dielectric','#234858'],['Bottom copper / signal','#dc9c69']]:[['Top copper','#e7b673'],['FR-4 dielectric (not a qualified RF model)','#234858'],['Bottom copper / possible GND','#dc9c69']];
$('pcbLayerDiagram').innerHTML=names.map(([n,col],i)=>`<div class="pcb-layer-strip ${col==='#234858'||col==='#28525f'?'insulator':''}" style="background:${col};color:${col==='#234858'||col==='#28525f'?'#c3e5e7':'#123034'}"><span>${n}</span><span>${i===0||i===names.length-1?`${fmt(spec.copper,3)} mm Cu`:'conceptual'}</span></div>`).join('')}
$('pcbStackPane').querySelectorAll('input,select').forEach(n=>n.addEventListener('input',compute));$('pcbApplyStack').onclick=()=>{let n=+$('pcbStackLayers').value,c=+$('pcbStackCopper').value,h=+$('pcbStackH').value,er=+$('pcbStackEr').value,t=+$('pcbStackThickness').value;if(![c,h,er,t].every(Number.isFinite)||c<=0||h<=0||er<2||t<.4)return notice('Enter valid positive stackup parameters.',true);commit(()=>{board.layers=n;board.stackup={...board.stackup,copper:c,signalHeight:h,er,thickness:t}});notice('Assumptions stored. Inner-layer routing remains conceptual.')};compute()
}
const lessons=[
{level:'FOUNDATIONS',name:'01 · Electrical requirements and constraints',intro:'Translate an idea into measurable design targets: voltage, load current, I/O, operating environment and test conditions.',steps:['Write supply tolerance, load current, startup and fault behavior.','Decide whether the board is a low-voltage educational circuit or an application requiring formal safety review.','Determine enclosure, mounting holes, environmental and connector constraints.'],task:'Open the LED design; identify the fused supply and ground return.',quiz:'Which item should be documented before selecting a trace width?',options:['Only the solder-mask colour','Operating current and fabrication constraints','The PCB file name'],answer:1},
{level:'FOUNDATIONS',name:'02 · Symbols, nets, pins and ERC',intro:'Understand schematic connectivity, power symbols, reference designators and hidden electrical hazards.',steps:['Match each component symbol to the manufacturer pin table.','Use explicit net labels; distinguish GND, chassis, analog ground and high-current return.','Run electrical-rule checking and check warnings rather than only counting them.'],task:'Switch to the netlist tab and inspect J1, F1 and the LED resistor.',quiz:'Does a clean PCB DRC prove that a schematic connects all IC supply pins correctly?',options:['Yes','No, the schematic also requires ERC and datasheet review'],answer:1},
{level:'FOUNDATIONS',name:'03 · Footprint verification and package geometry',intro:'Check body dimensions, pin numbering, pad dimensions, land pattern, pick-and-place orientation and clearance.',steps:['Read the exact ordered part datasheet and recommended land pattern.','Confirm polarity and pin-1 markers for LEDs, ICs and connectors.','Compare mechanical keepouts with chassis and mounting features.'],task:'Select the conceptual USB-C part and locate its non-manufacturable warning.',quiz:'Can a component named SOT-23-5 be assumed to share a universal functional pinout?',options:['Yes','No; package geometry does not define electrical pin functions'],answer:1},
{level:'FOUNDATIONS',name:'04 · Component placement and thermal clearance',intro:'Place power parts by functional current loops and mechanically critical connectors before general routing.',steps:['Anchor fixed connectors and mounting holes.','Put decoupling capacitors close to the physical power and ground pins.','Check airflow, thermal dissipation and accessible probes.'],task:'Drag C1 near the power entry and observe changes in distances and DRC.',quiz:'Why are input bypass capacitors placed close to a switching regulator?',options:['Reduce high-frequency current loop area','Increase screen brightness','Improve silkscreen readability'],answer:0},
{level:'FOUNDATIONS',name:'05 · Copper routing, vias and clearances',intro:'Route by net on top and bottom copper; study trace widths, annular rings, edge spacing, pad clearance and violations.',steps:['Select an assigned pad and route to a pad with the same net.','Use a via to change between copper sides.','Inspect remaining copper groups and resolve violations.'],task:'Finish all LED_A connections, then attempt a different-net route to see the short-circuit interlock.',quiz:'Can a trace on F.Cu connect directly to an isolated B.Cu trace without a plated transition?',options:['Yes','No; a via or plated through-hole transition is needed'],answer:1},
{level:'INTERMEDIATE',name:'06 · Return current and ground planes',intro:'The return path is part of every signal loop. Maintain a continuous return-reference network, particularly at high edge rates.',steps:['Distinguish ground polygons from mere copper colouring.','Study detours around slots and splits in planes.','Review stitching via placement and local decoupling paths.'],task:'Switch to four-layer concept in Stackup and locate the reference-plane position.',quiz:'What happens to high-frequency return current near a reference-plane split?',options:['A return-path detour can increase EMI','The current disappears','The signal becomes DC'],answer:0},
{level:'INTERMEDIATE',name:'07 · Four-layer design and stackup constraints',intro:'Compare two- and four-layer construction; separate layer count from actual manufacturable dielectric specification.',steps:['Choose layer order with reference-ground placement.','Request real prepreg/core thickness and dielectric data from the fabricator.','Do not assume a 1.6-mm board has a specific trace-to-plane spacing.'],task:'Change the stackup inputs and observe how the rough microstrip result changes.',quiz:'Who should confirm final controlled-impedance geometry?',options:['Any colour printer','PCB fabricator and validated field solver','The label on a schematic wire'],answer:1},
{level:'INTERMEDIATE',name:'08 · Decoupling and switching regulator layout',intro:'Follow the IC vendor layout reference for hot loop, switching node, bootstrap, feedback and ground.',steps:['Keep switching VIN-capacitor-ground loop short.','Route sensitive feedback away from noisy switching nodes.','Use the exact regulator pinout and compensation guidance.'],task:'Open the 3.3V sensor template, inspect U1 and its verification warning.',quiz:'Is a fixed 3.3V LDO pinout shared by every five-pin controller?',options:['Yes','No'],answer:1},
{level:'INTERMEDIATE',name:'09 · USB-C 5V sink design concepts',intro:'Learn CC1/CC2 pull-down concepts, Type-C mechanical selection, protection and current advertisement.',steps:['Understand independent Rd terminations for a simple sink.','Read the exact connector datasheet including orientation-dependent contacts.','Distinguish USB Type-C attachment from USB-PD voltage negotiation.'],task:'Inspect the USB-C concept template. Do not send it to fabrication.',quiz:'Do independent CC pull-downs alone negotiate arbitrary higher USB-PD voltages?',options:['No','Yes'],answer:0},
{level:'ADVANCED',name:'10 · Differential pairs, memory and interfaces',intro:'Study matched impedance, length and skew budgets for USB, PCIe, Ethernet, DDR and DisplayPort.',steps:['Obtain interface-specific design guide and target stackup.','Treat pair spacing and trace width as a coupled field-solver problem.','Budget vias, AC coupling, termination, layer changes and reference transitions.'],task:'Compare two widths in the rough microstrip tool. Note that it does not model differential coupling.',quiz:'Is matching trace lengths alone sufficient for a USB 3 or PCIe compliant layout?',options:['Yes','No; impedance, loss and signal-return control also matter'],answer:1},
{level:'ADVANCED',name:'11 · Power integrity and copper heating',intro:'Investigate DC drop, temperature, copper thickness, return-path spreading and transient response.',steps:['Estimate bulk plane and trace voltage drops.','Study IPC-2152 conditions for current-capacity decisions.','Consider copper weight tolerance, vias, local heat sources and ambient cooling.'],task:'Change trace width and current in Stackup; compare calculated ohmic loss.',quiz:'Can DC trace resistance by itself determine the safe continuous current rating?',options:['No','Yes'],answer:0},
{level:'ADVANCED',name:'12 · EMI, ESD, surge and analog isolation',intro:'Treat EMC and fault protection as system-level requirements, not decorative diodes.',steps:['Place TVS with a short discharge path and an appropriate reference.','Check ESD working/clamping voltages against protected pin limits.','Separate noisy switching and sensitive analog signals without breaking return paths.'],task:'Inspect the concept TVS in the USB-C trainer and identify unanswered datasheet requirements.',quiz:'Is any TVS diode with the correct package automatically appropriate for a 5V line?',options:['Yes','No, clamp and standoff must be checked'],answer:1},
{level:'RELEASE',name:'13 · DRC, ERC, review and fabrication files',intro:'Treat board layout as a version-controlled engineering release with electrical and mechanical evidence.',steps:['Run schematic ERC, layout DRC, 3D enclosure checks and vendor footprint comparison.','Confirm copper and drill constraints with the chosen PCB manufacturer.','Review Gerbers, Excellon drills, pick/place, assembly drawing and BOM in a real CAD workflow.'],task:'Run this training DRC, then download and independently check the experimental KiCad export.',quiz:'Does zero error count in this teaching editor authorize manufacturing?',options:['No','Yes'],answer:0},
{level:'RELEASE',name:'14 · Bring-up, DFT and hardware debugging',intro:'Plan for an accessible, safe first-power sequence with expected power rails and current limits.',steps:['Add test points and define safe ground references.','Document expected rails and safe power-up procedure.','Review thermal, functional, EMI and environmental validation requirements.'],task:'Return to the repair bench and apply fault diagnosis concepts to your board design review.',quiz:'What is most valuable in a first-revision PCB bring-up plan?',options:['Only a stylish solder mask','Accessible test points and defined measurements','Hiding all board labels'],answer:1}
];
function renderLearning(){let course=lessons[lessonIndex]||lessons[0];$('pcbLearningPane').innerHTML=`<div class="pcb-panel"><h3>PCB Design Academy · ${completed.length}/${lessons.length} lessons</h3><p>Progress is saved locally in this browser. Pass a concept question in each lesson to mark it complete; continue practising in the layout studio.</p><div class="pcb-stat-row"><div><strong>${completed.length}/${lessons.length}</strong><span>QUESTIONS PASSED</span></div><div><strong>${board.parts.length}</strong><span>FOOTPRINTS PLACED</span></div><div><strong>${K.check(board).percent}%</strong><span>COPPER CONNECTIVITY</span></div></div></div><div style="display:grid;grid-template-columns:minmax(230px,.9fr) minmax(340px,1.45fr);gap:14px" class="pcb-course-grid"><div>${lessons.map((l,i)=>`<button class="pcb-lesson-card ${completed.includes(i)?'done':''}" data-pcb-lesson="${i}" style="width:100%;text-align:left;grid-template-columns:27px 1fr"><span class="count">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(l.name.slice(5))}</strong><p>${esc(l.level)} · ${completed.includes(i)?'PASSED':'TO PRACTISE'}</p></span></button>`).join('')}</div><div class="pcb-panel"><span class="pcb-pill">${esc(course.level)} / LESSON ${lessonIndex+1}</span><h3 style="font-size:21px;margin-top:14px">${esc(course.name)}</h3><p>${esc(course.intro)}</p><div class="pcb-divider"></div><h3>Engineering workflow</h3><ol style="font-size:12px;line-height:1.8;color:#bad4db">${course.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="pcb-warning">PRACTICAL TASK: ${esc(course.task)}</div><h3 style="margin-top:21px">Knowledge checkpoint</h3><p>${esc(course.quiz)}</p><div style="display:grid;gap:8px" id="pcbAnswerOptions">${course.options.map((s,i)=>`<button data-answer="${i}" style="font-size:12px;text-align:left;padding:14px">${String.fromCharCode(65+i)}. ${esc(s)}</button>`).join('')}</div><div id="pcbQuizResult" style="margin:15px 0;color:#b9d8dd;font-size:12px"></div><button id="pcbLessonNext" class="pcb-primary" style="margin-top:12px">NEXT LESSON →</button></div></div>`;
$('pcbLearningPane').querySelectorAll('[data-pcb-lesson]').forEach(b=>b.onclick=()=>{lessonIndex=+b.dataset.pcbLesson;renderLearning()});
$('pcbLearningPane').querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{let n=+b.dataset.answer;if(n===course.answer){if(!completed.includes(lessonIndex)){completed.push(lessonIndex);try{localStorage.setItem(progressKey,JSON.stringify(completed))}catch{}}$('pcbQuizResult').textContent='✓ Correct. Lesson checkpoint passed. Apply this principle in a practical design review.';$('pcbQuizResult').style.color='#83f1ca';}else{$('pcbQuizResult').textContent='Not quite. Review the workflow and retry.';$('pcbQuizResult').style.color='#f2c08c'}});
$('pcbLessonNext').onclick=()=>{lessonIndex=(lessonIndex+1)%lessons.length;renderLearning()}
}
const releaseTasks=[
 ['spec','Requirements: voltages, maximum current, and environment documented'],
 ['schematic','Schematic electrical-rule check (ERC) completed in external EDA tool'],
 ['parts','Exact manufacturer part numbers and symbols verified'],
 ['pinouts','Every IC/connector pinout checked against manufacturer datasheets'],
 ['pads','Footprints and mechanical keepouts matched to supplier drawings'],
 ['rules','Track, via, drill, annular and edge rules confirmed by chosen PCB factory'],
 ['stack','Actual layer stack, dielectric and impedance specifications confirmed'],
 ['safety','ESD, battery, high-voltage and isolation risk review completed'],
 ['power','Power drop, decoupling, hot loops and thermal design reviewed'],
 ['signal','Signal integrity, return paths and interfaces reviewed if applicable'],
 ['drc','Full KiCad DRC and connectivity performed without unresolved critical findings'],
 ['3d','Mechanical fit, assembly orientation, 3D enclosure and connector reach reviewed'],
 ['files','Gerber, drill, assembly and BOM files inspected externally'],
 ['test','Test points, bring-up plan, current limits and production test documented']
];
let checklist={};try{checklist=JSON.parse(localStorage.getItem('boardlab.pcb.release.v3')||'{}')}catch{}
function renderRelease(){let c=K.check(board);$('pcbReleasePane').innerHTML=`<div class="pcb-panel"><h3>Design review · ${esc(board.title)}</h3><p>This studio teaches board-design workflow. It is not a replacement for a production EDA application or independent engineering review.</p><div class="pcb-stat-row"><div><strong>${c.errors}</strong><span>TRAINING DRC ERRORS</span></div><div><strong>${c.warnings}</strong><span>TRAINING DRC WARNINGS</span></div><div><strong>${c.percent}%</strong><span>NET PAD CONNECTIVITY</span></div></div><div class="pcb-warning">An exported file is <strong>NOT an approved manufacturing artifact</strong>. USB-C and SOT-23 training examples have conceptual pin mapping. External CAD DRC/ERC, datasheet and footprint verification, stackup review, thermal/EMC assessment and a professional manufacturing review remain mandatory.</div></div>
<div class="pcb-release-grid"><div class="pcb-panel"><h3>Project constraints</h3><div class="pcb-stack-controls" style="grid-template-columns:1fr 1fr"><label>Board width (mm)<input id="pcbBoardWidth" type="number" min="25" max="400" step="1" value="${board.width}"></label><label>Board height (mm)<input id="pcbBoardHeight" type="number" min="25" max="300" step="1" value="${board.height}"></label><label>Min trace (mm)<input id="pcbRuleTrack" type="number" min=".05" max="3" step=".05" value="${board.rules.minTrack}"></label><label>Min clearance (mm)<input id="pcbRuleClear" type="number" min=".05" max="3" step=".05" value="${board.rules.clearance}"></label><label>Copper-to-edge (mm)<input id="pcbRuleEdge" type="number" min=".1" max="5" step=".1" value="${board.rules.edge}"></label><label>Via drill (mm)<input id="pcbRuleViaDrill" type="number" min=".2" max="1.5" step=".05" value="${board.rules.viaDrill}"></label></div><button id="pcbApplyRules" class="pcb-primary" style="width:100%;margin-top:14px">APPLY TRAINING DESIGN RULES</button><p>These are user-selected teaching constraints, not guaranteed capabilities of a PCB manufacturer.</p><div class="pcb-divider"></div><h3>Export and import</h3><div class="pcb-export-grid"><button data-pcb-export="json">PROJECT .JSON</button><button data-pcb-export="svg">BOARD .SVG</button><button data-pcb-export="bom">BOM .CSV</button><button data-pcb-export="nets">NETLIST .CSV</button><button data-pcb-export="kicad">KiCad BOARD .KICAD_PCB*</button><button data-pcb-export="drc">DRC REPORT .TXT</button></div><label style="display:block;margin-top:13px">Import BOARD//LAB project (.json)<input type="file" id="pcbImportFile" accept="application/json,.json" style="margin-top:6px"></label><p>*KiCad board export is a training translation. The file uses illustrative footprints and may need adjustment for your KiCad version. Recreate/check the electrical schematic and rerun native KiCad DRC/3D review before fabrication.</p><button id="pcbResetProject" style="margin-top:6px">RESET TO NEW BLANK DESIGN</button></div>
<div class="pcb-panel"><h3>Professional manufacturing-readiness checklist</h3><p>These acknowledgements are for learning and do not constitute certification. They are not automatically checked by the PCB editor.</p>${releaseTasks.map(([id,title])=>`<div class="pcb-check"><label><input type="checkbox" data-release-check="${id}" ${checklist[id]?'checked':''}><span>${esc(title)}</span></label></div>`).join('')}<div class="pcb-warning">Electrical standards, safe creepage/clearance, EMI compliance and regulatory requirements are application dependent. Do not use training-board geometry for mains, battery packs, medical, aerospace, automotive safety or high-energy systems without qualified review.</div></div></div>`;
$('pcbApplyRules').onclick=()=>{const ids=[['pcbBoardWidth','width'],['pcbBoardHeight','height'],['pcbRuleTrack','minTrack'],['pcbRuleClear','clearance'],['pcbRuleEdge','edge'],['pcbRuleViaDrill','viaDrill']];let obj=Object.fromEntries(ids.map(([id,key])=>[key,Number($(id).value)]));if(!Object.values(obj).every(Number.isFinite)||obj.width<25||obj.width>400||obj.height<25||obj.height>300||obj.minTrack<=0||obj.clearance<=0||obj.edge<=0||obj.viaDrill<=0)return notice('Constraints are out of the permitted training range.',true);commit(()=>{board.width=obj.width;board.height=obj.height;Object.assign(board.rules,obj)});notice('Rules updated. Resolve new DRC issues before export.')};
$('pcbReleasePane').querySelectorAll('[data-release-check]').forEach(n=>n.onchange=()=>{checklist[n.dataset.releaseCheck]=n.checked;try{localStorage.setItem('boardlab.pcb.release.v3',JSON.stringify(checklist))}catch{}});
$('pcbReleasePane').querySelectorAll('[data-pcb-export]').forEach(b=>b.onclick=()=>exportDesign(b.dataset.pcbExport));
$('pcbImportFile').onchange=async e=>{let f=e.target.files?.[0];if(!f)return;if(f.size>1e6)return notice('Project file is above the 1 MB training limit.',true);try{let project=K.validateImport(JSON.parse(await f.text()));commit(()=>{board=project;selected=null;route=null});notice('Project imported and rechecked.')}catch(ex){notice('Cannot import: '+ex.message,true)}};
$('pcbResetProject').onclick=()=>{if(!window.confirm('Replace the current design with a blank training board? Export your JSON first if you need it.'))return;loadTemplate('blank')};
}
function exportDesign(kind){let title=(board.title||'board').replace(/[^a-z0-9_-]/gi,'_').slice(0,50);const d=K.check(board);
if(kind==='json')return downloadFile(title+'.json',JSON.stringify(board,null,2),'application/json');
if(kind==='bom')return downloadFile(title+'_BOM.csv',K.csv(board),'text/csv');
if(kind==='nets'){let rows=[['Net','Designator','Pin']];K.allPads(board).forEach(p=>rows.push([p.net||'UNASSIGNED',p.ref,p.pin]));const text=rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');return downloadFile(title+'_netlist.csv',text,'text/csv')}
if(kind==='drc')return downloadFile(title+'_DRC.txt',[`BOARD//LAB PCB TRAINING DESIGN REVIEW`,`Project: ${board.title}`,`Date: ${new Date().toISOString()}`,`Training DRC: ${d.errors} errors, ${d.warnings} warnings, ${d.percent}% pad connectivity`,`Not an official KiCad DRC, fab approval or certification.`,...d.issues.map(i=>`[${i.level}] ${i.code} — ${i.message}`)].join('\n'));
if(kind==='svg'){let svg=$('pcbBoardSvg').cloneNode(true);svg.querySelectorAll('[id^="pcb-glow"]').forEach(n=>n.remove());svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('width',board.width*12);svg.setAttribute('height',board.height*12);const s=document.createElementNS('http://www.w3.org/2000/svg','style');s.textContent='.pcb-silk-label{fill:#d3e2d0;font:1.25px monospace;font-weight:bold}.pcb-route-preview{stroke:#fff6ab;stroke-width:.25;stroke-dasharray:1 1;fill:none}.pcb-component.pcb-selected .pcb-body{stroke:#ffe29b}';svg.insertBefore(s,svg.firstChild);return downloadFile(title+'.svg',new XMLSerializer().serializeToString(svg),'image/svg+xml')}
if(kind==='kicad'){notice('Experimental KiCad-format PCB export: open and validate independently before use.');return downloadFile(title+'_TRAINING_ONLY.kicad_pcb',K.toKiCad(board),'application/x-kicad-pcb')}
}
function render(){populateNets();renderBoard();renderInspector();renderDRC();if(view==='schematic')renderSchematic();if(view==='stackup')renderStackup();if(view==='learning')renderLearning();if(view==='release')renderRelease()}
function init(){const nav=$('pcbNav');if(!nav)return;
// Capture navigation before the original v2 app handler to avoid activating its repair-only views.
document.addEventListener('click',e=>{const tab=e.target.closest?.('[data-tab]');if(!tab)return;if(tab.dataset.tab==='pcb'){e.preventDefault();e.stopImmediatePropagation();show()}else if(active){hide()}},true);
$('pcbSearchPart').oninput=renderPalette;$('pcbTemplate').onchange=()=>{};$('pcbLoadTemplate').onclick=()=>loadTemplate($('pcbTemplate').value);
$('pcbSave').onclick=()=>exportDesign('json');$('pcbRunDRC').onclick=()=>{let r=renderDRC();notice(`Training DRC: ${r.errors} errors, ${r.warnings} warnings; ${r.percent}% connected.`)};
$('pcbTools').querySelectorAll('[data-pcb-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.pcbTool));$('pcbActiveNet').onchange=()=>{renderBoard();renderInspector()};$('pcbActiveLayer').onchange=()=>{if(route)route=null;renderBoard()};
$('pcbTraceWidth').onchange=()=>{let n=+$('pcbTraceWidth').value;if(!Number.isFinite(n)||n<.05||n>5){$('pcbTraceWidth').value=.4;notice('Trace width must be between 0.05 and 5 mm.',true)}};
$('pcbUndo').onclick=undoEdit;$('pcbRedo').onclick=redoEdit;$('pcbCancelRoute').onclick=()=>{route=null;armed=null;renderBoard();renderPalette();$('pcbRouteStatus').textContent='ROUTE CANCELLED'};
$('pcbRatsnest').onclick=()=>{visible.rats=!visible.rats;$('pcbRatsnest').classList.toggle('pcb-toggle-on',visible.rats);renderBoard()};
$('pcbLayerTop').onclick=()=>{visible.top=!visible.top;$('pcbLayerTop').classList.toggle('pcb-toggle-on',visible.top);renderBoard()};
$('pcbLayerBottom').onclick=()=>{visible.bottom=!visible.bottom;$('pcbLayerBottom').classList.toggle('pcb-toggle-on',visible.bottom);renderBoard()};
$('pcbPerspective').onclick=()=>{visible.iso=!visible.iso;$('pcbCanvasWrap').classList.toggle('isometric',visible.iso);$('pcbPerspective').classList.toggle('pcb-toggle-on',visible.iso);$('pcbRouteStatus').textContent=visible.iso?'ISOMETRIC PREVIEW · SWITCH TO TOP VIEW TO EDIT':'TOP VIEW · EDITABLE'};
$('pcbResetView').onclick=()=>{visible.iso=false;$('pcbCanvasWrap').classList.remove('isometric');$('pcbPerspective').classList.remove('pcb-toggle-on');renderBoard()};
$('pcbBoardSvg').addEventListener('click',onBoardClick);$('pcbBoardSvg').addEventListener('pointermove',e=>{screenSvg(e);dragMove(e)});$('pcbBoardSvg').addEventListener('pointerup',dragFinish);$('pcbBoardSvg').addEventListener('pointercancel',dragFinish);
$('pcbBoardSvg').addEventListener('dblclick',e=>{if(route){e.preventDefault();e.stopPropagation();finishRoute()}});
$('pcbActiveLayer').value='F.Cu';document.querySelectorAll('[data-pcb-view]').forEach(b=>b.onclick=()=>setView(b.dataset.pcbView));
document.addEventListener('keydown',e=>{if(!active)return;if(e.key==='Escape'){route=null;armed=null;renderBoard();renderPalette()}if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redoEdit():undoEdit()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redoEdit()}if(e.key==='Delete'&&selected){let {id,kind}=selected;commit(()=>{if(kind==='part')board.parts=board.parts.filter(p=>p.id!==id);if(kind==='trace')board.tracks=board.tracks.filter(t=>t.id!==id);if(kind==='via')board.vias=board.vias.filter(v=>v.id!==id)});selected=null;render()}});
renderPalette();render();window.BoardLabPCB={getBoard:()=>src(),setBoard:b=>{board=K.validateImport(b);selected=null;route=null;saveLocal();render()},check:()=>K.check(board),selectTool:setTool,go:show,openView:setView,exportDesign};
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
